import { useEffect, useState } from "react";
import { Router, Route, Routes, Link, useNavigate } from "react-router-dom";
import { Col, Container, Row, Card } from "react-bootstrap";
import React from "react";
import { AdminUsers, AppContext } from "../Globals";
import BlogCard from '../elements/BlogCard';
import "./Blog.css"

import {auth, db} from '../firebase-config'
import styled, { css } from "styled-components";
import { deleteDoc, doc } from "firebase/firestore";
import { Helmet } from "react-helmet";
import MyCard from "../elements/MyCard";


export const ContextMenu = styled.div`
    z-index: 1;

  border-radius: 4px;
  box-sizing: border-box;
  position: absolute;
  width: 200px;
  background-color: #383838;
  box-shadow: 0px 1px 8px 0px rgba(0, 0, 0, 0.1);
  ${props => css`
    top: ${props.top}px;
    left: ${props.left}px;
  `}
  ul {
    list-style-type: none;
    box-sizing: border-box;
    margin: 0;
    padding: 10px;
  }
  ul li {
    padding: 18px 12px;
    border-radius: 4px;
  }

  ul li:hover {
    cursor: pointer;
    background-color:rgb(255, 255, 255);
  }
`;

export default function Blog() {
    const {posts, setPosts} = React.useContext(AppContext);
    const {isAuth, setIsAuth} = React.useContext(AppContext);
    const {authUser, setAuthUser} = React.useContext(AppContext);

    const [show, setShow] = useState(false);
    const [points, setPoints] = useState({x:0,y:0});

    const [selectedPost, setSelectedPost] = useState(posts[0]);

    const navigate = useNavigate();

    useEffect(() => {
        const handleClick = () => setShow(false);
        window.addEventListener('click', handleClick);
        return () => window.removeEventListener('click', handleClick);
    }, [])

    const createPostClick = () => {
        const data = { intent: 1 };
        navigate('/createpost', { state: data })
    }

    function deletePost() {
        if (authUser == AdminUsers[0]) {
        const postRef = doc(db, 'blogs', selectedPost.id);
        document.getElementById(selectedPost.id).remove();
        deleteDoc(postRef);
        }
    }
    return (
        <Container fluid>
            <Helmet>
                <title>Kara's Portfolio - Blog</title>
            </Helmet>
            <h1 className="border-bottom">Blog</h1>
            <br></br>
            <Row>
                {isAuth && authUser == AdminUsers[0] &&
                <Col className="" xs='12' sm='6' lg='4'>
                    <Card as={Link} onClick={createPostClick} to="/createpost" className="h-100 adminCard">
                        <h1 style={{textAlign:"center",margin:"auto", textDecoration:"none"}}>+</h1>
                    </Card>
                </Col>
                }

                {!posts.length < 1 ? posts.map((post) => (
                        <Col id={post.id} onContextMenu={(e) => {
                            console.log('Context Menu Opened');
                            e.preventDefault();
                            setShow(true);
                            console.log(e.pageX);
                            console.log(e.pageY);
                            setPoints({ x: e.pageX, y: e.pageY });
                
                            console.log(selectedPost.slug);
                          }} onMouseEnter={(e) => {setSelectedPost(post); console.log("yay")}} className="" xs='12' sm='6' lg='4'>
                            <MyCard isBlog="true"   post={post} imgsrc="./images/banner1.jpg" />
                        </Col>
                    )) : <h1>Nothing to see here</h1>}
            </Row>
            {show && authUser == AdminUsers[0] && <ContextMenu onContextMenu={(e) => {e.preventDefault(); setShow(false)}} top={points.y} left={points.x}>
            <ul>
                <li onClick={(e) => {
                    deletePost();
                }}>Delete Post</li>
            </ul>
        </ContextMenu>}
        </Container>
    )
}

