import { Card, Container,Row,Button } from "react-bootstrap";
import './ProjectCard.css'
import './BlogCard.css'
import { Link, useNavigate } from "react-router-dom";
import { parseTimestampString } from "../Parser";
import { useEffect, useState } from "react";
import styled, { css } from "styled-components";
import markdownToTxt from 'markdown-to-text';
import Markdown from "react-markdown";
import remarkGfm from "remark-gfm";
import remarkMath from "remark-math";
import rehypeKatex from "rehype-katex";

export default function MyCard({post, imgsrc, hasMax, useMarkdown, isBlog, title = post.title, subtitle = parseTimestampString(post.date), text = "", href = ""}) {
    const navigate = useNavigate();
    const maxChar = 180;
    function href() {
        if (isBlog == "true")
            return "/blog/" + post.slug;
        else return href;
    }

    function cutContent() {
        if (hasMax == 'false') return post.content;
        let str = post.content;
        if (post.content.length > maxChar) str = post.content.substring(0,maxChar) + "...";
        return str;
    }
    return (
        <Card className="projectCard blogCard h-100" as={Link} to={href()}>
            <Card.Img variant="top" src={imgsrc}></Card.Img>
            <Card.Body className="cardBody" style={{zIndex:"1", backgroundColor:"inherit"}}>
                <Card.Title>{title}</Card.Title>
                <Card.Subtitle>{subtitle}</Card.Subtitle>

                {isBlog == "true" ? <Card.Text><Markdown remarkPlugins={[remarkGfm, remarkMath]} rehypePlugins={[rehypeKatex]}>{cutContent()}</Markdown></Card.Text> : <Card.Text>{text}</Card.Text> }
            </Card.Body>
        </Card>
    );
    return(<Card as={Link} to={href} className="projectCard">
            <Card.Img variant="top" src={imgsrc}></Card.Img>
            <Card.ImgOverlay>
                <Card.Title>{title}</Card.Title>
                <Card.Subtitle>{subtitle}</Card.Subtitle>
            </Card.ImgOverlay>
            <Card.Body>
                
                <Card.Text>{text}</Card.Text>
            </Card.Body>
        </Card>);
}