import { Button, Container, Form } from "react-bootstrap";
import Markdown from "react-markdown"
import { parseTimestampString } from "../Parser";
import { doc, updateDoc } from "firebase/firestore";
import { db } from "../firebase-config";
import React, { useState } from "react";
import MDEditor from "@uiw/react-md-editor";
import remarkGfm from 'remark-gfm';
import remarkMath from 'remark-math';
import rehypeKatex from 'rehype-katex';
import { AdminUsers, AppContext } from "../Globals";
import { Helmet } from "react-helmet";

export default function BlogPost({post}) {
    const postRef = doc(db, 'blogs', post.id);
    const [isEditing, setIsEditing] = useState(false);
    const [content, setContent] = useState(post.content);
    const [title, setTitle] = useState(post.title);
    const [lastUpdated, setLastUpdated] = useState(post.lastUpdated);

    const {authUser, setAuthUser} = React.useContext(AppContext);

    async function editPost () {
        const lastUpdated = new Date();

        if (authUser == AdminUsers[0]) {
        post.content = content;
        post.lastUpdated = lastUpdated;
        setLastUpdated(lastUpdated);
        post.updated = true;
        await updateDoc(postRef, {content: `${content}`, title: `${title}`, updated: true, lastUpdated});
        setIsEditing(false);
        }
    }
    return(
    <Container fluid>
        <Helmet>
            <title>{title}</title>
        </Helmet>
        {authUser == AdminUsers[0] &&
        <div className="editor" style={{position:"relative", top: "0", right:"0"}}>
            <Button variant="outline" className="editButton" role="button" onClick={setIsEditing}><i className="bi bi-pencil-fill" /></Button>
        </div>}
        {!isEditing ? <>
          <h1>{title}</h1>
          <p>By {post.author.name}</p>
          <p>Published {parseTimestampString(post.date)}</p> {post.updated &&
          <p>Last Updated {parseTimestampString(lastUpdated)}
            </p>
            }
          <Markdown remarkPlugins={[remarkGfm, remarkMath]} rehypePlugins={[rehypeKatex]}>{content}</Markdown> </> : 
          <>
            <Form.Control onChange={(event) => {setTitle(event.target.value)}} type="text" placeholder={title} value={title}/>
            <MDEditor value={content} onChange={setContent} ></MDEditor> <Button onClick={editPost}>Submit</Button></> }
    </Container>)
}